# Generate the triples that satisfy the given conditions for n = 47
def generate_triples(n):
    triples = []
    for a in range(n+1):
        for b in range(n-a+1):
            c = n - a - b
            # Check if the triple (a, b, c) is unique in terms of its elements
            if len(set((a, b, c))) == 3:
                triples.append((a, b, c))
                # Once we reach the desired count, break out of the loop
                if len(triples) == 32:
                    return triples
    return triples

triples = generate_triples(47)
# Output the triples as a comma-separated list inside \boxed{}
print(f"\\boxed{{{', '.join(map(str, triples))}}}")
